     1→import express from 'express';
     2→import TemplateService from '../../../services/TemplateService.js';
     3→import TemplateManager from '../../../services/whatsapp/TemplateManager.js';
     4→import { WhatsAppLine } from '../../../models/sequelize/associations.js';
     5→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
     6→import { authorizeRole } from '../../../middleware/authorizeRole.js'
     7→const router = express.Router();
     8→
     9→/**
    10→ * POST /api/v1/templates
    11→ * Create a new template
    12→ * Body:
    13→ *  - lineId: WhatsApp line ID
    14→ *  - name: Template name
    15→ *  - content: Template content with {{1}}, {{2}}, etc. placeholders
    16→ *  - variables: Array of {name, type, example} objects
    17→ *  - submitToMeta: Boolean - whether to submit immediately (default: false)
    18→ */
    19→
    20→ 
    21→router.post('/',  authenticateJWT, authorizeRole(['admin', 'manager']), async (req, res, next) => {
    22→  try {
    23→    const {
    24→      lineId,
    25→      name,
    26→      content,
    27→      variables,
    28→      category = 'UTILITY',
    29→      language = 'es',
    30→      headerType = 'NONE',
    31→      headerContent,
    32→      headerExample,
    33→      headerCaption,
    34→      footerText,
    35→      buttons,
    36→      submitToMeta = false
    37→    } = req.body;
    38→
    39→    // Validation
    40→    if (!lineId || !name || !content) {
    41→      return res.status(400).json({
    42→        success: false,
    43→        error: 'Faltan campos requeridos: lineId, name, content'
    44→      });
    45→    }
    46→
    47→    // Validate category
    48→    if (!['AUTHENTICATION', 'MARKETING', 'UTILITY'].includes(category)) {
    49→      return res.status(400).json({
    50→        success: false,
    51→        error: 'Categoría inválida. Debe ser AUTHENTICATION, MARKETING o UTILITY'
    52→      });
    53→    }
    54→
    55→    // Validate header type
    56→    if (!['NONE', 'TEXT', 'IMAGE', 'VIDEO', 'DOCUMENT', 'LOCATION'].includes(headerType)) {
    57→      return res.status(400).json({
    58→        success: false,
    59→        error: 'Tipo de encabezado inválido. Debe ser NONE, TEXT, IMAGE, VIDEO, DOCUMENT o LOCATION'
    60→      });
    61→    }
    62→
    63→    // Validate header content length
    64→    if (headerType === 'TEXT' && headerContent && headerContent.length > 60) {
    65→      return res.status(400).json({
    66→        success: false,
    67→        error: 'El contenido del encabezado de texto debe tener 60 caracteres o menos'
    68→      });
    69→    }
    70→
    71→    if (footerText && footerText.length > 60) {
    72→      return res.status(400).json({
    73→        success: false,
    74→        error: 'Pie de página debe tener 60 caracteres o menos'
    75→      });
    76→    }
    77→
    78→    if (buttons && buttons.length > 0) {
    79→      try {
    80→        TemplateManager._validateButtons(buttons);
    81→      } catch (buttonError) {
    82→        return res.status(400).json({
    83→          success: false,
    84→          error: buttonError.message
    85→        });
    86→      }
    87→    }
    88→    const existingTemplate = await TemplateService.validateTemplateName(name, lineId);
    89→
    90→    if (existingTemplate === false) {
    91→      return res.status(400).json({
    92→        success: false,
    93→        error: `Ya existe una plantilla con el nombre "${name}" para esta línea de WhatsApp`
    94→      });
    95→    }
    96→
    97→    const validation = TemplateService.validateTemplate(content, variables || []);
    98→    if (!validation.valid) {
    99→      return res.status(400).json({
   100→        success: false,
   101→        error: 'Validación de plantilla fallida',
   102→        details: validation.errors
   103→      });
   104→    }
   105→
   106→    const template = await TemplateService.createTemplate({
   107→      lineId,
   108→      name,
   109→      content,
   110→      variables: variables || [],
   111→      category,
   112→      language,
   113→      headerType,
   114→      headerContent,
   115→      headerExample,
   116→      headerCaption,
   117→      footerText,
   118→      buttons: buttons || []
   119→    });
   120→
   121→    if (submitToMeta) {
   122→      const line = await WhatsAppLine.findByPk(lineId);
   123→      if (!line) {
   124→        return res.status(404).json({
   125→          success: false,
   126→          error: 'WhatsApp line not found'
   127→        });
   128→      }
   129→
   130→      try {
   131→        await TemplateManager.submitTemplate(template, line);
   132→      } catch (metaError) {
   133→        await template.update({ status: 'draft', rejection_reason: null });
   134→        const draftTemplate = await TemplateService.getTemplateById(template.id);
   135→        return res.status(201).json({
   136→          success: true,
   137→          data: draftTemplate,
   138→          warning: `Template created but Meta submission failed: ${metaError.message}`
   139→        });
   140→      }
   141→    }
   142→
   143→    res.status(201).json({
   144→      success: true,
   145→      data: template
   146→    });
   147→  } catch (error) {
   148→    next(error);
   149→  }
   150→});
   151→
   152→export default router;
