   446→
   447→  // Parsear formato de WhatsApp para vista previa
   448→  const parseWhatsAppFormatting = useCallback((text) => {
   449→    if (!text) return null;
   450→
   451→    // Escapar HTML primero
   452→    let html = text
   453→      .replace(/&/g, '&amp;')
   454→      .replace(/</g, '&lt;')
   455→      .replace(/>/g, '&gt;');
   456→
   457→    // Aplicar formato de código primero (```texto```)
   458→    html = html.replace(/```([^`]+)```/g, '<code class="wa-code">$1</code>');
   459→
   460→    // Negrita (*texto*)
   461→    html = html.replace(/\*([^*]+)\*/g, '<strong class="wa-bold">$1</strong>');
