   468→
   469→    // Reemplazar variables {{1}}, {{2}}, etc. con estilo
   470→    html = html.replace(/\{\{(\d+)\}\}/g, '<span class="wa-variable">{{$1}}</span>');
   471→
   472→    // Preservar saltos de línea
   473→    html = html.replace(/\n/g, '<br />');
   474→
   475→    return html;
   476→  }, []);
   477→
   478→  // Generar contenido con ejemplos para la vista previa
   479→  const getPreviewContent = useCallback(() => {
