  1014→                    {formData.headerType === 'DOCUMENT' && (
  1015→                      <div className="wa-message-document">
  1016→                        <i className="bi bi-file-earmark-text"></i>
  1017→                        <span>{formData.headerFilename || 'Documento'}</span>
  1018→                      </div>
  1019→                    )}
