  1025→                    />
  1026→
  1027→                    {/* Footer */}
  1028→                    {formData.footerText && (
  1029→                      <div className="wa-message-footer">
  1030→                        {formData.footerText}
  1031→                      </div>
  1032→                    )}
  1033→
  1034→                    {/* Timestamp */}
