  1044→                        <div key={index} className="wa-button">
  1045→                          {btn.type === 'URL' && <i className="bi bi-box-arrow-up-right me-2"></i>}
  1046→                          {btn.type === 'PHONE_NUMBER' && <i className="bi bi-telephone me-2"></i>}
  1047→                          {btn.type === 'QUICK_REPLY' && <i className="bi bi-reply me-2"></i>}
  1048→                          {btn.text || 'Botón'}
  1049→                        </div>
  1050→                      ))}
  1051→                    </div>
  1052→                  )}
  1053→                </div>
  1054→              </div>
