/**
 * Axios API Client
 *
 * Configured Axios instance with interceptors for:
 * - Authentication (JWT token injection)
 * - Token refresh on 401
 * - Error handling
 * - Request/response logging
 */

import axios from 'axios';

/**
 * Create Axios instance with base configuration
 */
const api = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api',
  timeout: 30000, // 30 seconds
  headers: {
    'Content-Type': 'application/json'
  }
});

/**
 * Token management
 */
let accessToken = null;
let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
  failedQueue.forEach(prom => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });

  failedQueue = [];
};

/**
 * Set access token
 *
 * @param {string} token - JWT access token
 */
export const setAuthToken = (token) => {
  accessToken = token;
};

/**
 * Get current access token
 *
 * @returns {string|null} Current access token
 */
export const getAuthToken = () => {
  return accessToken;
};

/**
 * Clear access token
 */
export const clearAuthToken = () => {
  accessToken = null;
};

/**
 * Request interceptor
 * Injects authentication token into requests
 */
api.interceptors.request.use(
  (config) => {
    // Add access token if available
    if (accessToken) {
      config.headers.Authorization = `Bearer ${accessToken}`;
    }

    // Log request in development
    if (import.meta.env.DEV) {
      console.log(`[API Request] ${config.method?.toUpperCase()} ${config.url}`, {
        params: config.params,
        data: config.data
      });
    }

    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

/**
 * Response interceptor
 * Handles token refresh and error responses
 */
api.interceptors.response.use(
  (response) => {
    // Log response in development
    if (import.meta.env.DEV) {
      console.log(`[API Response] ${response.config.method?.toUpperCase()} ${response.config.url}`, {
        status: response.status,
        data: response.data
      });
    }

    return response;
  },
  async (error) => {
    const originalRequest = error.config;

    // Log error in development
    if (import.meta.env.DEV) {
      console.error(`[API Error] ${originalRequest?.method?.toUpperCase()} ${originalRequest?.url}`, {
        status: error.response?.status,
        data: error.response?.data
      });
    }

    // Handle 401 Unauthorized - attempt token refresh
    // Skip token refresh for login and refresh endpoints
    const isAuthEndpoint = originalRequest.url?.includes('/auth/login') ||
                          originalRequest.url?.includes('/auth/refresh');

    if (error.response?.status === 401 && !originalRequest._retry && !isAuthEndpoint) {
      if (isRefreshing) {
        // Queue this request while refreshing
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        })
          .then(token => {
            originalRequest.headers.Authorization = `Bearer ${token}`;
            return api(originalRequest);
          })
          .catch(err => {
            return Promise.reject(err);
          });
      }

      originalRequest._retry = true;
      isRefreshing = true;

      try {
        // Attempt to refresh token
        const response = await axios.post(
          `${api.defaults.baseURL}/auth/refresh`,
          {},
          {
            withCredentials: true // Send httpOnly cookie
          }
        );

        const newToken = response.data.accessToken;

        // Update token
        setAuthToken(newToken);

        // Process queued requests
        processQueue(null, newToken);

        // Retry original request with new token
        originalRequest.headers.Authorization = `Bearer ${newToken}`;
        return api(originalRequest);

      } catch (refreshError) {
        // Refresh failed - clear auth and redirect to login
        processQueue(refreshError, null);
        clearAuthToken();

        // Emit custom event for auth failure (handled by auth store)
        window.dispatchEvent(new CustomEvent('auth:logout', {
          detail: { reason: 'Token refresh failed' }
        }));

        return Promise.reject(refreshError);

      } finally {
        isRefreshing = false;
      }
    }

    // Handle other errors
    const errorData = {
      message: error.response?.data?.message || error.message || 'An error occurred',
      status: error.response?.status,
      data: error.response?.data
    };

    return Promise.reject(errorData);
  }
);

/**
 * API request helpers
 */

/**
 * GET request
 *
 * @param {string} url - Endpoint URL
 * @param {Object} config - Axios config
 * @returns {Promise} Response data
 */
export const get = async (url, config = {}) => {
  const response = await api.get(url, config);
  return response.data;
};

/**
 * POST request
 *
 * @param {string} url - Endpoint URL
 * @param {Object} data - Request body
 * @param {Object} config - Axios config
 * @returns {Promise} Response data
 */
export const post = async (url, data = {}, config = {}) => {
  const response = await api.post(url, data, config);
  return response.data;
};

/**
 * PUT request
 *
 * @param {string} url - Endpoint URL
 * @param {Object} data - Request body
 * @param {Object} config - Axios config
 * @returns {Promise} Response data
 */
export const put = async (url, data = {}, config = {}) => {
  const response = await api.put(url, data, config);
  return response.data;
};

/**
 * PATCH request
 *
 * @param {string} url - Endpoint URL
 * @param {Object} data - Request body
 * @param {Object} config - Axios config
 * @returns {Promise} Response data
 */
export const patch = async (url, data = {}, config = {}) => {
  const response = await api.patch(url, data, config);
  return response.data;
};

/**
 * DELETE request
 *
 * @param {string} url - Endpoint URL
 * @param {Object} config - Axios config
 * @returns {Promise} Response data
 */
export const del = async (url, config = {}) => {
  const response = await api.delete(url, config);
  return response.data;
};

/**
 * Upload file
 *
 * @param {string} url - Endpoint URL
 * @param {FormData} formData - Form data with file
 * @param {Function} onUploadProgress - Progress callback
 * @returns {Promise} Response data
 */
export const upload = async (url, formData, onUploadProgress = null) => {
  const response = await api.post(url, formData, {
    headers: {
      'Content-Type': 'multipart/form-data'
    },
    onUploadProgress: onUploadProgress
      ? (progressEvent) => {
          const percentCompleted = Math.round(
            (progressEvent.loaded * 100) / progressEvent.total
          );
          onUploadProgress(percentCompleted);
        }
      : undefined
  });
  return response.data;
};

export default api;

content.text:
Encontré el problema. El interceptor de `api.js` transforma el error antes de que llegue al servicio (línea 184-190):

```js
const errorData = {
  message: error.response?.data?.message || ...,  // busca 'message', no 'error'
  data: error.response?.data   // { success: false, error: '...', details: [...] }
};
return Promise.reject(errorData);  // plain object, no axios error
```

La API devuelve el campo `error`, pero el interceptor busca `message`. Entonces `templateService.createTemplate` hace `error.response?.data?.error` — pero el `error` ya es el plain object del interceptor que no tiene `.response`. El mensaje real está en `error.data.error`.

Hay que corregir `templateService.js` en los métodos `createTemplate` y `updateTemplate`:

